// Кейсы: .qa/tests/devices/DEV-012.md, DEV-014.md (шаги 1–2) · план: .qa/e2e-app/specs/app.md (1.36)
// ПОЛУАВТОМАТ (@manual-assist @data): главный iPhone — Appium; второй телефон (Pixel 6 / любой) — человек, затем Enter в терминале.
// Удаляет второй телефон («הסרה») и возвращает его по QR. Только с BANCI_MANUAL_ASSIST=1 И BANCI_REMOVE_PHONE=1, иначе пропуск.
// Если человек не вернул телефон — состояние аккаунта 1/2: вернуть вручную по QR (DEV-012 шаги 5–7).
import { createInterface } from 'node:readline/promises';
import { by, assert, skip } from '../../lib/appium.mjs';
import { openDevices, secondRowText, SECOND, LIMIT, STATUS_ON } from './devices-helpers.mjs';
import { openAddPhone, closeSheet } from './add-phone-sheet.test.mjs';

export const name = 'Удаление второго телефона → он сам выходит на «כניסה» с «הטלפון הוסר מהחשבון», пароль отклонён → возврат по QR → «מכשיר נוסף · מקבל התרעות» #272dc6 #83f7f9 @iphone @app @data @manual-assist';

async function waitHuman(prompt) {
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  try {
    const answer = rl.question(prompt);
    const limit = new Promise((_, rej) => setTimeout(() => rej(new Error('человек не подтвердил «готово» за 10 мин')), 600000));
    return String(await Promise.race([answer, limit])).trim();
  } finally {
    rl.close();
  }
}

export default async function (app) {
  if (process.env.BANCI_MANUAL_ASSIST !== '1' || process.env.BANCI_REMOVE_PHONE !== '1') {
    skip('полуавтомат @data: удаляет второй телефон и возвращает его по QR руками — запуск только с BANCI_MANUAL_ASSIST=1 и BANCI_REMOVE_PHONE=1');
  }

  // 1. Главный: «מכשירים» → второй телефон → «הסרת הטלפון מהחשבון» → «הסרה».
  await openDevices(app);
  await app.scrollTo(SECOND, { max: 3, what: 'строка «מכשיר נוסף»' }).catch(() => null);
  const before = await secondRowText(app);
  if (before === null) skip('нет дополнительного телефона — удалять нечего (подключить по QR)');
  console.log(`     удаляем: «${before}»`);
  await waitHuman('     РУЧНОЙ ШАГ: на втором телефоне откройте приложение (передний план, ничего не трогать) и нажмите Enter: ');
  await (await app.waitFor(SECOND, { what: 'строка «מכשיר נוסף»' })).click();
  await app.tap(by.exact('הסרת הטלפון מהחשבון'), { what: '«הסרת הטלפון מהחשבון»' });
  await app.waitFor(by.contains('הטלפון ייצא מהחשבון'), { what: 'окно удаления «הטלפון ייצא מהחשבון.»' });
  await app.tap(by.exact('הסרה'), { what: 'кнопка «הסרה»' });

  // 2. Главный: второго телефона нет в списке, сообщения о лимите нет (S-03 AC6).
  await app.waitGone(SECOND, { timeout: 20000, what: 'строка «מכשיר נוסף» после «הסרה»' });
  assert(!(await app.exists(by.contains(LIMIT))), `после удаления нет «${LIMIT}…» (слот освободился)`);
  await app.screenshot('272dc6-auto-devices-after-remove');
  const removedAt = Date.now();

  // 3–4. РУЧНОЙ ШАГ на втором: экран «כניסה» с «הטלפון הוסר מהחשבון», вход паролем отклонён.
  const a1 = await waitHuman(
    '     РУЧНОЙ ШАГ (второй телефон): дождитесь экрана «כניסה» с «הטלפון הוסר מהחשבון» (без перезапуска),\n' +
    '     затем введите email/пароль dadayo → «כניסה» — должна быть та же ошибка.\n' +
    '     Всё так → Enter. Не так → напишите, что видно, и Enter: ');
  console.log(`     выход на втором подтверждён через ~${Math.round((Date.now() - removedAt) / 1000)} с после «הסרה» (с учётом ввода пароля)`);
  assert(!a1, `второй телефон: ${a1}`);

  // 5. Главный: «הוספת טלפון» → QR («הקוד פעיל 10 דקות»).
  await app.restart();
  const state = await openAddPhone(app);
  assert(state === 'qr', 'после удаления есть свободный слот — шторка с QR, а не сообщение о лимите');
  await app.waitFor(by.contains('הקוד פעיל 10 דקות'), { what: '«הקוד פעיל 10 דקות»' });

  // 6. РУЧНОЙ ШАГ: второй сканирует QR, входит, на системный запрос уведомлений — «Allow» (#83f7f9).
  const a2 = await waitHuman(
    '     РУЧНОЙ ШАГ (второй телефон): сканируйте QR камерой, войдите; появился системный запрос уведомлений → «Allow».\n' +
    '     Запрос был и телефон в аккаунте → Enter. Не так → напишите, что видно, и Enter: ');
  assert(!a2, `второй телефон после QR: ${a2}`);

  // 7. Главный: «סגירה» → «מכשירים»: второй снова «מכשיר נוסף · מקבל התרעות» (опрос с перезагрузкой списка, до 2 мин).
  await closeSheet(app);
  const end = Date.now() + 120000;
  let row = null;
  while (Date.now() < end) {
    await app.restart();
    await openDevices(app);
    row = await secondRowText(app);
    if (row && (row.includes(STATUS_ON) || (await app.exists(by.contains(STATUS_ON))))) break;
  }
  console.log(`     строка второго после QR: «${row}»`);
  assert(row !== null, 'второй телефон снова в «מכשירים» после QR');
  assert(row.includes(STATUS_ON) || (await app.exists(by.contains(STATUS_ON))), `второй телефон «מכשיר נוסף · ${STATUS_ON}» (сейчас «${row}»)`);
  await app.screenshot('272dc6-auto-devices-after-rejoin');
  await app.restart();
}
